/* Spawns a type 6 particle with position, colour, scale and owner. */
void create_spark_particle(int owner, float *pos, int snd, unsigned char arg, unsigned char idx, unsigned char mode,
                           float x, float y, float z, float scale, float f21, float r, float g, float b, float a) {
    float buf[4];
    float *tmp = buf;
    struct PartBase *p;
    unsigned char *u;
    *(u128 *)tmp = *(u128 *)pos;
    if (owner != 0) {
        p = (struct PartBase *)create_part(6);
        if (p != 0) {
            u = (unsigned char *)p->data;
            qcopy(&p->pos, tmp);
            if (mode == 0xFF) {
                p->unk_09 = ((arg >> 5) << 4) + truncate_float_to_s32(4.0f);
                if (arg & 1)
                    p->blend = 0x48;
                else
                    p->blend = 0x44;
            } else {
                p->unk_09 = arg;
                p->blend = mode;
            }
            p->unk_01 = 0;
            p->texture = *novalis_part_type_textures[idx];
            *(float *)u = x;
            *(float *)(u + 4) = y;
            *(float *)(u + 8) = z;
            *(float *)(u + 0x14) = f21;
            u[0x18] = truncate_float_to_s32(r * 65535.0f);
            u[0x19] = truncate_float_to_s32(g * 65535.0f);
            u[0x1A] = truncate_float_to_s32(b * 65535.0f);
            *(float *)(u + 0x10) = a;
            *(int *)(u + 0xC) = owner;
            p->size = scale;
            p->spin = (int)(f21 * 255.0f);
            p->timer = scale_ticks(snd);
            u[0x1B] = 0;
            p->color = PackColorRGBA(r, g, b, a);
        }
    }
}
